import java.io.*;
import java.util.*;

public class COVID {

    static int[] factorial;
    static final int MOD = 998244353;

    static int modPow(int base, long exp, int mod) {
        int result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (int) ((result * 1L * base) % mod);
            }
            base = (int) ((base * 1L * base) % mod);
            exp >>= 1;
        }
        return result;
    }

    static long nCr(int n, int r) {
        long numerator = factorial[n];
        long denominator = (factorial[n - r] * 1L * factorial[r]) % MOD;
        long invDenom = modPow((int) denominator, MOD - 2, MOD);
        return (numerator * invDenom) % MOD;
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        long k = sc.nextLong();

        if (k > n - 1) {
            pw.println(0);
            pw.flush();
            pw.close();
            return;
        }

        factorial = new int[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int) ((factorial[i - 1] * 1L * i) % MOD);
        }

        int pop = n - (int) k;
        long ans = 0;

        for (int i = 0; i <= pop; i++) {
            long term = (nCr(pop, i) * modPow(pop - i, n, MOD)) % MOD;
            if (i % 2 == 1) {
                term = (term * -1 + MOD) % MOD;
            }
            ans = (ans + term) % MOD;
        }

        ans = (ans * nCr(n, pop)) % MOD;
        if (k != 0) {
            ans = (ans * 2) % MOD;
        }

        pw.println(ans);
        pw.flush();
        pw.close();
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static int logBase(int n, int base) {
        int result = 0;
        while (n + 1 > base) {
            result++;
            n /= base;
        }
        return result;
    }

    static long square(long x) {
        return x * x;
    }

    static class Pair implements Comparable<Pair> {
        int x, y;

        Pair(int a, int b) {
            x = a;
            y = b;
        }

        @Override
        public int compareTo(Pair other) {
            if (x != other.x) {
                return Integer.compare(x, other.x);
            }
            return Integer.compare(y, other.y);
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Pair pair = (Pair) obj;
            return x == pair.x && y == pair.y;
        }
    }

    static class Scanner {
        private BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public Scanner(String filename) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(filename));
        }

        public long[] nextLongArray(int size) throws IOException {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        public int[] nextIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine(), " ,");
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            String token = next();
            double result = 0;
            boolean negative = false;
            boolean decimal = false;
            double divisor = 1;

            int start = 0;
            if (token.charAt(0) == '-') {
                negative = true;
                start = 1;
            }

            for (int i = start; i < token.length(); i++) {
                char c = token.charAt(i);
                if (c == '.') {
                    decimal = true;
                } else {
                    result = result * 10 + (c - '0');
                    if (decimal) {
                        divisor *= 10;
                    }
                }
            }

            result /= divisor;
            return negative ? -result : result;
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }

    public static void shuffle(int[] arr) {
        Random rand = new Random();
        for (int i = arr.length - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
